package com.rezoxnemesis.videostudio;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;
/** Actual normal native installer helper with bounded synthetic protobuf, no model/art inference. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE)
public class LocalDrawingPlusInstallFileTest {
 byte[] original,prepared;File stage;JSONObject item;
 @Before public void fixture()throws Exception {LocalDrawingPlusGraphConverterTest graph=new LocalDrawingPlusGraphConverterTest();graph.fixture();java.lang.reflect.Method clip=graph.getClass().getDeclaredMethod("clip",boolean.class,boolean.class);clip.setAccessible(true);original=(byte[])clip.invoke(graph,false,false);prepared=(byte[])clip.invoke(graph,true,false);stage=Files.createTempDirectory("native-plus-install-").toFile();item=new JSONObject().put("path","image_encoder/model.onnx").put("bytes",prepared.length).put("sha256",SketchDocument.sha256(prepared)).put("derivedFrom",new JSONObject().put("recipe","clip_penultimate_v1").put("bytes",original.length).put("sha256",SketchDocument.sha256(original)).put("url","https://huggingface.co/test/resolve/"+"a".repeat(40)+"/model.onnx"));}
 File target(){return new File(stage,"image_encoder/model.onnx");}
 File privateSource()throws Exception{return new File(stage,".native_sources/"+item.getJSONObject("derivedFrom").getString("sha256")+".onnx");}
 @Test public void normalHelperConvertsSourceAndOnlyCleansItsOwnVerifiedTemporary()throws Exception {File unrelated=new File(stage,"published-existing.onnx");Files.write(unrelated.toPath(),new byte[]{7,8});AtomicInteger fetches=new AtomicInteger();JSONObject proof=LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->{fetches.incrementAndGet();assertEquals(item.getJSONObject("derivedFrom").getString("sha256"),descriptor.getString("sha256"));Files.write(destination.toPath(),original);},null);assertEquals(1,fetches.get());assertEquals(item.getString("sha256"),proof.getString("resultSha256"));assertArrayEquals(prepared,Files.readAllBytes(target().toPath()));assertFalse(privateSource().exists());assertArrayEquals(new byte[]{7,8},Files.readAllBytes(unrelated.toPath()));assertTrue(LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->fail("Verified final file must not redownload"),null).getBoolean("reused"));}
 @Test public void conversionCancellationPreservesPrivateSourceAndPreviousTargetForRetry()throws Exception {assertTrue(target().getParentFile().mkdirs());byte[] old={9,6,3};Files.write(target().toPath(),old);AtomicInteger fetches=new AtomicInteger();Exception cancelled=assertThrows(Exception.class,()->LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->{fetches.incrementAndGet();Files.write(destination.toPath(),original);},n->{if(n>256*1024)throw new CancellationException("cancel install conversion");}));assertTrue(cancelled.toString().contains("cancel"));assertArrayEquals(old,Files.readAllBytes(target().toPath()));assertArrayEquals(original,Files.readAllBytes(privateSource().toPath()));LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->fail("Retry retains verified private source"),null);assertEquals(1,fetches.get());assertArrayEquals(prepared,Files.readAllBytes(target().toPath()));assertFalse(privateSource().exists());}
 @Test public void wrongDownloadAndDerivedPinsNeverPublishOrCleanOtherFiles()throws Exception {assertTrue(target().getParentFile().mkdirs());Files.write(target().toPath(),new byte[]{4,5});assertThrows(Exception.class,()->LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->Files.write(destination.toPath(),new byte[]{1,2}),null));assertArrayEquals(new byte[]{4,5},Files.readAllBytes(target().toPath()));JSONObject wrong=new JSONObject(item.toString()).put("sha256","f".repeat(64));assertThrows(Exception.class,()->LocalDrawingModelFileInstall.prepare(stage,wrong,(descriptor,destination)->Files.write(destination.toPath(),original),null));assertArrayEquals(new byte[]{4,5},Files.readAllBytes(target().toPath()));assertArrayEquals(original,Files.readAllBytes(privateSource().toPath()));}
 @Test public void retryAfterPublicationCleansOnlyVerifiedPrivateSourceBeforeActivation()throws Exception {assertTrue(target().getParentFile().mkdirs());assertTrue(privateSource().getParentFile().mkdirs());Files.write(target().toPath(),prepared);Files.write(privateSource().toPath(),original);assertTrue(LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->fail("Published result must never redownload"),null).getBoolean("reused"));assertFalse(privateSource().exists());assertFalse(new File(stage,".native_sources").exists());assertArrayEquals(prepared,Files.readAllBytes(target().toPath()));}
 @Test public void escapeAndSymlinkTargetsCannotReceiveConvertedWeights()throws Exception {JSONObject escape=new JSONObject(item.toString()).put("path","../escape.onnx");assertThrows(Exception.class,()->LocalDrawingModelFileInstall.prepare(stage,escape,(descriptor,destination)->fail("Unsafe path must fail before fetch"),null));File outside=Files.createTempFile("outside-model-",".onnx").toFile();assertTrue(target().getParentFile().mkdirs());Files.createSymbolicLink(target().toPath(),outside.toPath());assertThrows(Exception.class,()->LocalDrawingModelFileInstall.prepare(stage,item,(descriptor,destination)->fail("Symlink must fail before fetch"),null));assertEquals(0,outside.length());}
}
